/** Financial correctness regressions: real frontend functions with synthetic requests only. */
const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const Module=require('node:module');
const ts=require('typescript');
const root=path.resolve(__dirname,'..');
// Reuse the established harness definitions without registering their test cases.
function harnessDefinitions(file,marker,exports){const filename=path.join(__dirname,file),source=fs.readFileSync(filename,'utf8'),end=source.indexOf(marker);assert.ok(end>0,`${file} harness boundary`);const m=new Module(filename,module);m.filename=filename;m.paths=module.paths;m._compile(source.slice(0,end)+`\nmodule.exports={${exports}};`,filename);return m.exports;}
const invoice=harnessDefinitions('invoice-handlers.test.cjs','\nwithCase(','harness,fixtureInvoice,success,failure,all,text');
const quotes=harnessDefinitions('quotation-handlers.test.cjs','\nfor(const status','harness,ready,validNew,draftItem,all,label');
const orders=harnessDefinitions('orders-handlers.test.cjs','\ncheck(','harness,stock,fulfillment,success,failure,all,text');
function caseWith(name,factory,run){test(name,async()=>{const h=factory();try{await run(h);}finally{h.cleanup();}});}
for(const [savedMode,currentMode,total,tax] of [[null,'inclusive',110,10],['exclusive','inclusive',110,10],['inclusive','exclusive',121,11]]){
 caseWith(`Quotation Review follows current ${currentMode}, not saved ${savedMode}`,()=>quotes.harness(),h=>{
  if(savedMode){quotes.ready(h);h.setState('core',{...h.state('core'),tax_calculation_mode:savedMode});}else quotes.validNew(h);
  h.setState('taxMode',currentMode);h.setState('tab','review');h.setState('items',[{...quotes.draftItem,quantity:1,unit_price:110,discount_percent:0,tax_rate:10}]);
  const reviewProps=quotes.all(h.render(),'ReviewTab')[0].props;assert.equal(reviewProps.taxMode,currentMode);
  const review=h.helpers.ReviewTab(reviewProps),row=quotes.all(review,'tbody')[0];assert.match(quotes.label(row),new RegExp(`USD ${total}\\.00`));
  const totals=Object.fromEntries(quotes.all(review,'Total').map(n=>[n.props.label,n.props.value]));assert.equal(totals.Total,`USD ${total.toFixed(2)}`);assert.equal(totals[currentMode==='inclusive'?'Tax included':'Tax'],`USD ${tax.toFixed(2)}`);
 });
}
caseWith('Quotation inclusive discount/zero tax stays consistent between Pricing and Review',()=>quotes.harness(),h=>{
 quotes.validNew(h);h.setState('taxMode','inclusive');h.setState('items',[{...quotes.draftItem,quantity:2,unit_price:110,discount_percent:10,tax_rate:0}]);h.setState('tab','pricing');const pricing=h.helpers.PricingTab(quotes.all(h.render(),'PricingTab')[0].props);h.setState('tab','review');const review=h.helpers.ReviewTab(quotes.all(h.render(),'ReviewTab')[0].props);for(const tree of [pricing,review]){const totals=Object.fromEntries(quotes.all(tree,'Total').map(n=>[n.props.label,n.props.value]));assert.equal(totals.Total,'USD 198.00');assert.equal(totals['Tax included'],'USD 0.00');}
});
caseWith('Quotation print remains saved-only and absent in edit mode',()=>quotes.harness(),h=>{const edit=quotes.ready(h,'draft','edit');assert.equal(quotes.all(edit,'button').some(n=>/Print \/ PDF/.test(quotes.label(n))),false);const view=quotes.ready(h,'draft','view');assert.match(quotes.label(view),/Print \/ PDF uses the saved version/);});
for(const mode of ['inclusive','exclusive'])caseWith(`Invoice note-only draft edit preserves ${mode} saved mode`,()=>invoice.harness('detail'),async h=>{
 const saved={...invoice.fixtureInvoice,tax_calculation_mode:mode,total:mode==='inclusive'?'110':'121',balance_due:mode==='inclusive'?'110':'121',items:[{...invoice.fixtureInvoice.items[0],quantity:'1',unit_price:'110',tax_rate:'10',line_total:mode==='inclusive'?'110':'121'}]};
 h.setResponse(url=>invoice.success(url.includes('/payments?')?[]:saved));h.render();await h.handlers().load();h.setState('form',{...h.state('form'),notes:'Only this note changed'});h.render();h.handlers().beginEdit();h.render();await h.handlers().saveDraft();const patch=h.requests.find(r=>r.options?.method==='PATCH');assert.ok(patch);const payload=JSON.parse(patch.options.body);assert.equal(payload.tax_calculation_mode,mode);assert.equal(payload.items[0].unit_price,110);assert.equal(payload.items[0].tax_rate,10);assert.equal(payload.notes,'Only this note changed');
});
for(const mode of [undefined,null,'invalid'])caseWith(`Invoice unknown tax mode ${mode} fails closed without PATCH`,()=>invoice.harness('detail'),async h=>{h.setResponse(url=>invoice.success(url.includes('/payments?')?[]:{...invoice.fixtureInvoice,tax_calculation_mode:mode}));h.render();await h.handlers().load();h.render();h.handlers().beginEdit();h.render();await h.handlers().saveDraft();assert.equal(h.requests.filter(r=>r.options?.method==='PATCH').length,0);assert.match(h.state('error'),/tax mode could not be verified/);});
caseWith('Invoice edit labels saved totals and PDF does not include unsaved changes',()=>invoice.harness('detail'),async h=>{h.render();await h.handlers().load();h.setState('editing',true);const tree=h.render();assert.match(invoice.text(tree),/Totals shown are the saved invoice values/);assert.match(invoice.text(tree),/not unsaved changes/);assert.ok(invoice.all(tree,'Summary').some(n=>n.props.label==='Saved total'));assert.equal(invoice.all(tree,'a').some(n=>n.props.href?.startsWith('/print/invoices/')),false);});
function readyStock(h,props){h.render(props);h.set('loading',false);h.set('warehouseId','synthetic-warehouse');h.set('fulfillmentDate','2026-10-26');h.set('quantities',{'stock-line':'1'});return h.render(props);}
const submit={preventDefault(){}};
caseWith('Fulfillment duplicate synchronous submits produce exactly one POST',()=>orders.harness('fulfillment'),async h=>{readyStock(h);let finish;h.response((_u,o)=>o?.method==='POST'?new Promise(r=>{finish=r;}):orders.success([]));const first=h.handlers().submit(submit);await h.handlers().submit(submit);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);finish(orders.success(orders.fulfillment));await first;});
caseWith('Uncertain fulfillment retry reuses the same key and exact payload',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response(()=>{throw new TypeError('Synthetic interrupted response');});await h.handlers().submit(submit);h.render();await h.handlers().submit(submit);const writes=h.requests.filter(r=>r.options?.method==='POST');assert.equal(writes.length,2);assert.equal(writes[0].options.headers['Idempotency-Key'],writes[1].options.headers['Idempotency-Key']);assert.equal(writes[0].options.body,writes[1].options.body);assert.equal(h.state('uncertain'),true);});
caseWith('Changed operation cannot silently replace an uncertain fulfillment key',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response(()=>{throw new TypeError('Synthetic interrupted response');});await h.handlers().submit(submit);h.set('quantities',{'stock-line':'2'});h.render();await h.handlers().submit(submit);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);assert.match(h.state('error'),/uncertain outcome.*unchanged request/);});
caseWith('Definitive validation rejection allows corrected payload with a new key',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response(()=>orders.failure(422));await h.handlers().submit(submit);h.set('quantities',{'stock-line':'2'});h.render();await h.handlers().submit(submit);const writes=h.requests.filter(r=>r.options?.method==='POST');assert.equal(writes.length,2);assert.notEqual(writes[0].options.headers['Idempotency-Key'],writes[1].options.headers['Idempotency-Key']);});
caseWith('Known fulfillment success plus callback failure stays locked without reposting',()=>orders.harness('fulfillment'),async h=>{const props={onFulfilled:async()=>{throw new Error('Synthetic readback failure');}};readyStock(h,props);h.response((_u,o)=>o?.method==='POST'?orders.success(orders.fulfillment):orders.success([]));await h.handlers().submit(submit);h.render(props);await h.handlers().submit(submit);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);assert.match(h.state('error'),/saved.*status could not be refreshed/);assert.ok(h.state('confirmedBeforeStock'));});
caseWith('Known success plus history failure retries only reads, not POST',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response((_u,o)=>o?.method==='POST'?orders.success(orders.fulfillment):orders.failure(503));await h.handlers().submit(submit);h.render();await h.handlers().refreshSavedStatus();assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);assert.match(h.state('error'),/saved.*status could not be refreshed/);});
caseWith('Resolved callback with stale stock props cannot unlock confirmed fulfillment',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response((_u,o)=>o?.method==='POST'?orders.success(orders.fulfillment):orders.success([]));await h.handlers().submit(submit);h.render();await h.handlers().submit(submit);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);assert.equal(h.handlers().refreshRequired,true);});
caseWith('Fresh stock props plus verified history permits a genuinely new dispatch key',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response((_u,o)=>o?.method==='POST'?orders.success(orders.fulfillment):orders.success([]));await h.handlers().submit(submit);h.set('quantities',{'stock-line':'1'});h.render({items:[{...orders.stock,fulfilled_quantity:'3',remaining_quantity:'2'}]});assert.equal(h.handlers().refreshRequired,false);await h.handlers().submit(submit);const writes=h.requests.filter(r=>r.options?.method==='POST');assert.equal(writes.length,2);assert.notEqual(writes[0].options.headers['Idempotency-Key'],writes[1].options.headers['Idempotency-Key']);});
caseWith('Uncertain reversal retries retain key and reversal payload',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.handlers().beginReverse(orders.fulfillment);h.set('reverseReason','Synthetic reversal');h.set('reverseDate','2026-10-26');h.render();h.response(()=>{throw new TypeError('Synthetic lost reversal response');});await h.handlers().reverse(orders.fulfillment);h.render();await h.handlers().reverse(orders.fulfillment);const writes=h.requests.filter(r=>r.options?.method==='POST');assert.equal(writes.length,2);assert.equal(writes[0].options.headers['Idempotency-Key'],writes[1].options.headers['Idempotency-Key']);assert.equal(writes[0].options.body,writes[1].options.body);});
caseWith('Reversal and dispatch share one synchronous in-flight guard',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.set('reverseReason','Synthetic reversal');h.render();let finish;h.response((_u,o)=>o?.method==='POST'?new Promise(r=>{finish=r;}):orders.success([]));const first=h.handlers().reverse(orders.fulfillment);await h.handlers().submit(submit);await h.handlers().reverse(orders.fulfillment);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);finish(orders.success({...orders.fulfillment,status:'reversed'}));await first;});
function proxyHarness(){const calls=[],cookies=[];let response=async()=>new Response('{}',{status:200,headers:{'content-type':'application/json'}});const filename=path.join(root,'src/lib/tenant-proxy.ts'),m=new Module(filename,module);m.filename=filename;m.paths=module.paths;class NextResponse extends Response {static json(value,init){return new NextResponse(JSON.stringify(value),init);}}m.require=id=>{if(id==='next/server')return{NextResponse};if(id==='@/lib/auth-session')return{setAuthCookies:(_r,v)=>cookies.push(v)};if(id==='@/lib/server-api')return{backendFetch:async(p,o)=>{calls.push({path:p,options:o});return response(p,o);}};if(id==='@/lib/mutation-origin'){const child=new Module(filename,module);child.filename=filename;child.paths=module.paths;child.require=m.require;child._compile(ts.transpileModule(fs.readFileSync(path.join(root,'src/lib/mutation-origin.ts'),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,filename);return child.exports;}if(id==='@/lib/request-context'){const child=new Module(filename,module);child.filename=filename;child.paths=module.paths;child._compile(ts.transpileModule(fs.readFileSync(path.join(root,'src/lib/request-context.ts'),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,filename);return child.exports;}throw new Error('Unexpected proxy dependency '+id);};m._compile(ts.transpileModule(fs.readFileSync(filename,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,filename);return{calls,cookies,proxy:m.exports.proxyTenantRequest,respond:fn=>{response=fn;}};}
function request(key){return{url:'https://preview.example.invalid/api/sales/orders/synthetic/fulfillments',method:'POST',headers:new Headers({'Origin':'https://preview.example.invalid','Content-Type':'application/json','x-request-id':'synthetic-request',...(key?{'Idempotency-Key':key}:{})}),cookies:{get:name=>({value:name==='organization_id'?'synthetic-company':name==='access_token'?'synthetic-access':'synthetic-refresh'})},arrayBuffer:async()=>new TextEncoder().encode('{"synthetic":true}').buffer};}
test('Tenant proxy forwards explicit idempotency key, body and tenant context unchanged',async()=>{const h=proxyHarness();await h.proxy(request('synthetic-operation-key'),'/sales/orders/synthetic/fulfillments');assert.equal(h.calls.length,1);assert.equal(h.calls[0].options.headers['Idempotency-Key'],'synthetic-operation-key');assert.equal(h.calls[0].options.headers['X-Organization-ID'],'synthetic-company');assert.equal(new TextDecoder().decode(h.calls[0].options.body),'{"synthetic":true}');});
test('Tenant proxy reuses key only on business retry, never on auth refresh',async()=>{const h=proxyHarness();let business=0;h.respond(async p=>p==='/auth/refresh'?new Response(JSON.stringify({access_token:'synthetic-new',refresh_token:'synthetic-new-refresh'}),{status:200}):new Response('{}',{status:++business===1?401:200}));await h.proxy(request('synthetic-retry-key'),'/sales/orders/synthetic/fulfillments');assert.equal(h.calls.length,3);assert.equal(h.calls[0].options.headers['Idempotency-Key'],'synthetic-retry-key');assert.equal(h.calls[1].path,'/auth/refresh');assert.equal(h.calls[1].options.headers['Idempotency-Key'],undefined);assert.equal(h.calls[2].options.headers['Idempotency-Key'],'synthetic-retry-key');assert.equal(h.calls[2].options.body,h.calls[0].options.body);});
test('Tenant proxy does not invent an idempotency key',async()=>{const h=proxyHarness();await h.proxy(request(),'/sales/orders/synthetic/fulfillments');assert.equal(h.calls[0].options.headers['Idempotency-Key'],undefined);});

caseWith('Unchanged retry survives newer stock quantities and ignores edited form values',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response(()=>{throw new TypeError('Synthetic response interrupted');});await h.handlers().submit(submit);const original=h.requests[0].options;h.set('quantities',{'stock-line':'99'});h.set('reference','Changed after uncertainty');h.render({items:[{...orders.stock,fulfilled_quantity:'5',remaining_quantity:'0'}]});await h.handlers().retryUnchanged();assert.equal(h.requests.length,2);assert.equal(h.requests[1].options.body,original.body);assert.equal(h.requests[1].options.headers['Idempotency-Key'],original.headers['Idempotency-Key']);});
caseWith('Known reversal success followed by failed refresh cannot reverse twice',()=>orders.harness('fulfillment'),async h=>{const props={onFulfilled:async()=>{throw new Error('Synthetic refresh failed');}};readyStock(h,props);h.set('reverseReason','Synthetic reversal');h.render(props);h.response(()=>orders.success({...orders.fulfillment,status:'reversed'}));await h.handlers().reverse(orders.fulfillment);h.render(props);await h.handlers().reverse(orders.fulfillment);await h.handlers().retryUnchanged();assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);assert.match(h.state('error'),/saved.*status could not be refreshed/);});

caseWith('Stock number formatting alone cannot unlock a confirmed posting',()=>orders.harness('fulfillment'),async h=>{readyStock(h);h.response((_u,o)=>o?.method==='POST'?orders.success(orders.fulfillment):orders.success([]));await h.handlers().submit(submit);h.render({items:[{...orders.stock,fulfilled_quantity:'2.0000',remaining_quantity:'3.0000'}]});assert.equal(h.handlers().refreshRequired,true);await h.handlers().submit(submit);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);});

function moneyModule(){const filename=path.join(root,'src/lib/sales-money-preview.ts'),m=new Module(filename,module);m.filename=filename;m.paths=module.paths;m._compile(ts.transpileModule(fs.readFileSync(filename,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,filename);return m.exports;}
