test('Exact preview matches 144 actual backend Decimal HALF_UP oracle vectors',()=>{const money=moneyModule();for(const vector of decimalOracleVectors)assert.deepEqual(money.salesLinePreview(vector.input,vector.mode),vector.expected,JSON.stringify(vector.input)+' '+vector.mode);});
test('Multi-line totals sum already rounded line cents, not unrounded intermediates',()=>{const money=moneyModule(),line=money.salesLinePreview({quantity:3,unit_price:.05,discount_percent:10,tax_rate:10},'exclusive');assert.deepEqual(line,{subtotal:'0.15',discount:'0.02',taxable:'0.13',tax:'0.01',total:'0.14'});assert.deepEqual(money.salesTotalsPreview([line,line]),{subtotal:'0.30',discount:'0.04',tax:'0.02',total:'0.28'});});
test('Exact formatter preserves cents beyond safe integer cents and negative half cents',()=>{const money=moneyModule();assert.equal(money.formatMoneyExact('98999999999999.01','USD'),'USD 98,999,999,999,999.01');assert.equal(money.formatMoneyExact('-0.005','USD'),'USD -0.01');assert.equal(money.formatMoneyExact('0.005','USD'),'USD 0.01');});
test('Scientific input mirrors the existing Number payload serialization',()=>{const money=moneyModule();assert.equal(money.salesLinePreview({quantity:'3e0',unit_price:'5e-2',discount_percent:'1e1',tax_rate:'1e1'},'exclusive').total,'0.14');assert.equal(money.salesLinePreview({quantity:'1',unit_price:'1e-7',discount_percent:'',tax_rate:''},'inclusive').total,'0.00');});
test('Empty and invalid required quantity, nonfinite, negative and oversized previews are unavailable',()=>{const money=moneyModule(),base={quantity:'1',unit_price:'1',discount_percent:'0',tax_rate:'0'};for(const patch of [{quantity:''},{quantity:'0'},{quantity:'-1'},{quantity:'NaN'},{quantity:'Infinity'},{unit_price:'-0.01'},{unit_price:'1e400'},{unit_price:'1'.repeat(101)},{quantity:'1e10'},{discount_percent:'100.01'},{tax_rate:'-1'},{tax_rate:'1000.01'}])assert.equal(money.salesLinePreview({...base,...patch},'exclusive'),null,JSON.stringify(patch));assert.equal(money.salesLinePreview(base,'unknown'),null);assert.deepEqual(money.salesTotalsPreview([null]),{subtotal:'',discount:'',tax:'',total:''});assert.equal(money.formatMoneyExact('','USD'),'USD —');});
test('Zero price and empty optional percentages preserve accepted payload behavior',()=>{const money=moneyModule();assert.equal(money.salesLinePreview({quantity:'1',unit_price:'',discount_percent:'',tax_rate:''},'exclusive').total,'0.00');assert.equal(money.salesLinePreview({quantity:'1',unit_price:'5',discount_percent:'100',tax_rate:'100'},'exclusive').total,'0.00');});
caseWith('Quotation Pricing and Review use backend-rounded 0.14, not old 0.15 estimate',()=>quotes.harness(),h=>{quotes.validNew(h);h.setState('taxMode','exclusive');h.setState('items',[{...quotes.draftItem,quantity:3,unit_price:.05,discount_percent:10,tax_rate:10}]);for(const tab of ['pricing','review']){h.setState('tab',tab);const type=tab==='pricing'?'PricingTab':'ReviewTab',tree=h.helpers[type](quotes.all(h.render(),type)[0].props),totals=Object.fromEntries(quotes.all(tree,'Total').map(n=>[n.props.label,n.props.value]));assert.equal(totals.Total,'USD 0.14');assert.equal(totals.Discount,'- USD 0.02');assert.equal(totals.Tax,'USD 0.01');}});
caseWith('Active invoice create estimate uses exact rounded line totals and exact sums',()=>invoice.harness('list'),h=>{h.render();const line={...h.state('form').lines[0],quantity:'3',unit_price:'0.05',discount_percent:'10',tax_rate:'10'};h.setState('form',{...h.state('form'),lines:[line,line],tax_calculation_mode:'exclusive'});h.render();assert.equal(h.handlers().draftTotal,'0.28');});

test('Tenant proxy rejects a foreign mutation Origin before any backend or refresh call',async()=>{const h=proxyHarness(),r=request('synthetic-origin-key');r.headers.set('Origin','https://foreign.example.invalid');const response=await h.proxy(r,'/sales/orders/synthetic/fulfillments');assert.equal(response.status,403);assert.equal(h.calls.length,0);});
